def get_S(L, n, k):
    S = []
    for i in range(1 << n):
        s = bin(i)[2:].zfill(n)
        dist = sum(1 for a, b in zip(L, s) if a != b)
        if dist == k:
            S.append(s)
    return sorted(S)

def find_ambiguities(n, k):
    ambiguities = {}
    for i in range(1 << n):
        L = bin(i)[2:].zfill(n)
        S = tuple(get_S(L, n, k))
        if S in ambiguities:
            ambiguities[S].append(L)
        else:
            ambiguities[S] = [L]

    max_m = 0
    for S in ambiguities:
        max_m = max(max_m, len(ambiguities[S]))
    return max_m

for n in range(3, 10):
    for k in range(1, n // 2 + 1):
        if n > 2*k:
            print(f"n={n}, k={k}, max_m={find_ambiguities(n, k)}")

